const KEY='fjp-flow-v1';
const defaultTasks=[
 {id:crypto.randomUUID(),title:'Revisar os afazeres da semana',date:todayISO(),time:'09:00',duration:20,priority:'important',category:'Pessoal',guide:'Observe os próximos sete dias e escolha somente três prioridades principais.',reminder:true,done:false,notified:false},
 {id:crypto.randomUUID(),title:'Organizar documentos pendentes',date:todayISO(),time:'14:00',duration:30,priority:'normal',category:'Trabalho',guide:'Separe primeiro os documentos por assunto; depois descarte as versões duplicadas.',reminder:true,done:false,notified:false}
];
let state=load();let currentFocus=null;let timerSeconds=1500;let timerHandle=null;let searchTerm='';let filterMode='all';
const $=s=>document.querySelector(s);const $$=s=>document.querySelectorAll(s);
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function load(){try{const data=JSON.parse(localStorage.getItem(KEY))||{tasks:defaultTasks,focusMinutes:0,dark:false};data.tasks=data.tasks.map(t=>({...t,energy:t.energy||'medium',repeat:t.repeat||'none'}));return data}catch{return{tasks:defaultTasks,focusMinutes:0,dark:false}}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function escapeHTML(v=''){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function formatDate(iso){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(iso+'T12:00:00'))}
function guideFor(title,category){const t=title.toLowerCase();if(t.includes('pagar')||t.includes('conta'))return 'Confirme o vencimento, abra o aplicativo do banco e deixe o comprovante salvo.';if(t.includes('organizar'))return 'Separe tudo em três grupos: manter, resolver e descartar. Comece pelo menor.';if(t.includes('estudar')||category==='Estudo')return 'Defina um assunto pequeno, elimine distrações e faça uma sessão curta de revisão.';if(t.includes('ligar')||t.includes('falar'))return 'Anote em uma frase o resultado que deseja obter antes de iniciar o contato.';if(t.includes('comprar'))return 'Faça uma lista curta, confira o que já possui e defina um limite de gasto.';if(category==='Saúde')return 'Prepare o necessário com antecedência e escolha uma versão simples que você consiga iniciar agora.';return 'Comece pela menor ação concreta que deixa esta tarefa visivelmente mais próxima do fim.'}
function taskSort(a,b){const p={urgent:0,important:1,normal:2};return a.done-b.done||a.date.localeCompare(b.date)||(a.time||'23:59').localeCompare(b.time||'23:59')||p[a.priority]-p[b.priority]}
function isOverdue(t){return !t.done&&new Date(`${t.date}T${t.time||'23:59'}:00`)<new Date()}
function energyText(v){return v==='high'?'energia alta':v==='low'?'energia baixa':'energia média'}
function nextRepeatDate(iso,repeat){const d=new Date(iso+'T12:00:00');if(repeat==='daily')d.setDate(d.getDate()+1);if(repeat==='weekly')d.setDate(d.getDate()+7);if(repeat==='monthly')d.setMonth(d.getMonth()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function filtered(tasks){return tasks.filter(t=>{const text=(t.title+' '+t.category).toLowerCase();if(searchTerm&&!text.includes(searchTerm))return false;if(filterMode==='urgent'&&t.priority!=='urgent')return false;if(filterMode==='overdue'&&!isOverdue(t))return false;if(filterMode==='quick'&&t.duration>20)return false;return true})}
function render(){state.tasks.sort(taskSort);renderToday();renderInbox();renderWeek();renderProgress();save()}
function taskHTML(t,completed=false){return `<article class="task-item priority-${t.priority} ${completed?'completed-item':''}" data-id="${t.id}"><input class="task-check" type="checkbox" ${t.done?'checked':''} aria-label="Concluir ${escapeHTML(t.title)}"><div class="task-copy"><strong>${escapeHTML(t.title)}</strong><small><span><i class="category-dot"></i>${escapeHTML(t.category)}</span><span class="${isOverdue(t)?'overdue-badge':''}">${isOverdue(t)?'Atrasada · ':''}${formatDate(t.date)}${t.time?' · '+t.time:''}</span><span>${t.duration} min</span><span class="energy-badge">◇ ${energyText(t.energy)}</span>${t.repeat!=='none'?'<span>↻ recorrente</span>':''}</small></div><div class="task-menu">${!t.done?'<button class="start-button">Começar</button><button class="postpone-button" title="Passar para amanhã">Amanhã</button>':''}<button class="edit-button" aria-label="Editar tarefa">Editar</button><button class="delete-button" aria-label="Excluir tarefa">×</button></div></article>`}
function renderToday(){const todayAll=state.tasks.filter(t=>(t.date===todayISO()||isOverdue(t))&&!t.done);const today=filtered(todayAll);const done=state.tasks.filter(t=>t.date===todayISO()&&t.done);const pct=todayAll.length+done.length?Math.round(done.length/(todayAll.length+done.length)*100):0;$('#progressPercent').textContent=pct+'%';$('#progressRing').style.setProperty('--progress',`${pct*3.6}deg`);$('#openTotal').textContent=todayAll.length;$('#minutesTotal').textContent=todayAll.reduce((s,t)=>s+t.duration,0)+' min';$('#summaryGreeting').textContent=done.length?'Você já colocou o dia em movimento.':'Vamos colocar o dia em movimento?';$('#summaryText').textContent=done.length?`${done.length} ${done.length===1?'tarefa concluída':'tarefas concluídas'}. Continue no seu ritmo.`:'Escolha poucas tarefas importantes e avance uma etapa de cada vez.';$('#routeList').innerHTML=today.map(t=>taskHTML(t)).join('');$('#routeEmpty').style.display=today.length?'none':'block';const next=today[0];$('#nowContent').innerHTML=next?`<h3>${escapeHTML(next.title)}</h3><div class="now-meta"><span>${next.time||'Sem horário'}</span><span>•</span><span>${next.duration} minutos</span></div><div class="guide-box"><strong>Primeiro passo</strong>${escapeHTML(next.guide||guideFor(next.title,next.category))}</div><button class="primary-button focus-trigger" data-id="${next.id}">Começar agora</button>`:'<div class="now-placeholder"><span>✓</span><p>Nenhuma tarefa encontrada.</p></div>';bindTasks()}
function renderInbox(){const open=state.tasks.filter(t=>!t.done);$('#inboxList').innerHTML=open.length?open.map(t=>taskHTML(t)).join(''):'<div class="empty-state"><div class="empty-symbol">⌁</div><h3>Caixa de entrada vazia</h3><p>Ótimo. Tudo o que importa já foi resolvido.</p></div>';$('#inboxCount').textContent=open.length;$('#inboxCount').style.display=open.length?'block':'none';bindTasks()}
function renderWeek(){const base=new Date();const day=(base.getDay()+6)%7;base.setDate(base.getDate()-day);const names=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];$('#weekBoard').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(base.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const tasks=state.tasks.filter(t=>t.date===iso&&!t.done);return `<section class="day-column ${iso===todayISO()?'today':''}"><h3>${names[i]}</h3><span>${d.getDate()} de ${d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span>${tasks.map(t=>`<div class="week-task"><strong>${escapeHTML(t.title)}</strong><small>${t.time||'Livre'} · ${t.duration} min</small></div>`).join('')||'<div class="week-task"><small>Dia livre</small></div>'}</section>`}).join('')}
function renderProgress(){const done=state.tasks.filter(t=>t.done);$('#statCompleted').textContent=done.length;$('#statOpen').textContent=state.tasks.length-done.length;$('#statFocus').textContent=state.focusMinutes+'m';$('#completedList').innerHTML=done.length?done.slice().reverse().map(t=>taskHTML(t,true)).join(''):'<div class="empty-state"><h3>Seu progresso começa na primeira conclusão</h3><p>Conclua um afazer para vê-lo aqui.</p></div>';bindTasks()}
function bindTasks(){$$('.task-item').forEach(el=>{const id=el.dataset.id;el.querySelector('.task-check').onchange=e=>{const t=state.tasks.find(x=>x.id===id);t.done=e.target.checked;t.completedAt=t.done?new Date().toISOString():null;if(t.done&&t.repeat!=='none'&&!state.tasks.some(x=>x.parentRepeat===t.id)){state.tasks.push({...t,id:crypto.randomUUID(),date:nextRepeatDate(t.date,t.repeat),done:false,notified:false,completedAt:null,parentRepeat:t.id})}toast(t.done?'Boa! Mais uma etapa concluída.':'Tarefa reaberta.');render()};el.querySelector('.delete-button').onclick=()=>{state.tasks=state.tasks.filter(x=>x.id!==id);toast('Afazer removido.');render()};el.querySelector('.edit-button').onclick=()=>editTask(id);const postpone=el.querySelector('.postpone-button');if(postpone)postpone.onclick=()=>{const t=state.tasks.find(x=>x.id===id),d=new Date();d.setDate(d.getDate()+1);t.date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;t.notified=false;toast('Afazer passado para amanhã.');render()};const start=el.querySelector('.start-button');if(start)start.onclick=()=>openFocus(id)});$$('.focus-trigger').forEach(b=>b.onclick=()=>openFocus(b.dataset.id))}
function showView(name){$$('.view').forEach(v=>v.classList.remove('active-view'));$('#'+name+'View').classList.add('active-view');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={today:'Sua rota de hoje',inbox:'Caixa de entrada',week:'Mapa da semana',progress:'Seu progresso'};$('#viewTitle').textContent=titles[name]}
function openModal(){const modal=$('#taskModal');$('#taskForm').reset();$('#taskId').value='';$('#taskDate').value=todayISO();$('#modalLabel').textContent='NOVO AFAZER';$('#modalTitle').textContent='O que precisa sair do papel?';$('#saveTaskButton').textContent='Adicionar à rota';modal.showModal();setTimeout(()=>$('#taskTitle').focus(),50)}
function editTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;$('#taskId').value=t.id;$('#taskTitle').value=t.title;$('#taskDate').value=t.date;$('#taskTime').value=t.time||'';$('#taskDuration').value=t.duration;$('#taskPriority').value=t.priority;$('#taskCategory').value=t.category;$('#taskEnergy').value=t.energy||'medium';$('#taskRepeat').value=t.repeat||'none';$('#taskGuide').value=t.guide||'';$('#taskReminder').checked=t.reminder;$('#modalLabel').textContent='EDITAR AFAZER';$('#modalTitle').textContent='Ajuste sua rota';$('#saveTaskButton').textContent='Salvar alterações';$('#taskModal').showModal()}
function closeModal(){$('#taskModal').close();$('#taskForm').reset()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),2600)}
function openFocus(id){currentFocus=state.tasks.find(t=>t.id===id);if(!currentFocus)return;timerSeconds=currentFocus.duration*60;$('#focusTitle').textContent=currentFocus.title;$('#focusGuide').textContent=currentFocus.guide||guideFor(currentFocus.title,currentFocus.category);updateTimer();$('#focusModal').showModal()}
function updateTimer(){const m=Math.floor(timerSeconds/60),s=timerSeconds%60;$('#focusTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function stopTimer(){clearInterval(timerHandle);timerHandle=null;$('#focusToggle').textContent='Continuar'}
function checkReminders(){if(Notification.permission!=='granted')return;const now=Date.now();state.tasks.forEach(t=>{if(!t.reminder||t.done||t.notified||!t.time)return;const due=new Date(`${t.date}T${t.time}:00`).getTime();if(due-now>0&&due-now<=600000){new Notification('FJP Flow',{body:`Em breve: ${t.title}`,icon:'icon.svg'});t.notified=true;save()}})}
$('#taskForm').addEventListener('submit',e=>{e.preventDefault();const title=$('#taskTitle').value.trim();if(!title)return;const id=$('#taskId').value;const values={title,date:$('#taskDate').value,time:$('#taskTime').value,duration:Number($('#taskDuration').value),priority:$('#taskPriority').value,category:$('#taskCategory').value,energy:$('#taskEnergy').value,repeat:$('#taskRepeat').value,guide:$('#taskGuide').value.trim()||guideFor(title,$('#taskCategory').value),reminder:$('#taskReminder').checked,notified:false};if(id){Object.assign(state.tasks.find(t=>t.id===id),values);toast('Alterações salvas.')}else{state.tasks.push({id:crypto.randomUUID(),...values,done:false});toast('Afazer adicionado à sua rota.')}closeModal();render()});
$$('.add-task-trigger').forEach(b=>b.onclick=openModal);$('#openTaskModal').onclick=openModal;$('#mobileAdd').onclick=openModal;$('#closeTaskModal').onclick=closeModal;$('#cancelTaskModal').onclick=closeModal;$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#sortButton').onclick=()=>{state.tasks.sort(taskSort);toast('Rota reorganizada por prazo e prioridade.');render()};$('#taskSearch').oninput=e=>{searchTerm=e.target.value.trim().toLowerCase();renderToday()};$('#taskFilter').onchange=e=>{filterMode=e.target.value;renderToday()};
$('#notificationButton').onclick=async()=>{if(!('Notification'in window))return toast('Alertas não são suportados neste navegador.');const p=await Notification.requestPermission();toast(p==='granted'?'Alertas ativados.':'Permissão de alertas não concedida.')};
$('#themeButton').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);$('#themeButton').textContent=state.dark?'☀':'☾';save()};
$('#focusToggle').onclick=()=>{if(timerHandle){stopTimer();return}$('#focusToggle').textContent='Pausar';timerHandle=setInterval(()=>{timerSeconds--;if(timerSeconds<=0){stopTimer();state.focusMinutes+=currentFocus.duration;toast('Sessão de foco concluída!');if(Notification.permission==='granted')new Notification('FJP Flow',{body:'Sua sessão terminou. Quer concluir a tarefa?'});timerSeconds=0}updateTimer()},1000)};
$('#finishFocus').onclick=()=>{if(currentFocus){currentFocus.done=true;currentFocus.completedAt=new Date().toISOString();state.focusMinutes+=Math.max(1,Math.round((currentFocus.duration*60-timerSeconds)/60))}stopTimer();$('#focusModal').close();toast('Tarefa concluída. Excelente avanço!');render()};$('#closeFocusModal').onclick=()=>{stopTimer();$('#focusModal').close()};
const now=new Date();$('#todayDate').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(now);document.body.classList.toggle('dark',state.dark);$('#themeButton').textContent=state.dark?'☀':'☾';
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');setInterval(checkReminders,30000);render();
